INSERT OR IGNORE INTO product (id, product_number, handle, title, subtitle, description_html, status, thumbnail, unit, product_type, delivery_type, primary_category_id, option_title, option_display, shipping_size, pages, series, release_date, preorder, editorial_reviews) VALUES ('prd_noble-quran-bewley', 101, 'noble-quran-bewley', 'The Noble Qur''an', 'A New Rendering of its Meaning in English', '<p>The Noble Quran The Noble Qur''an: A New Rendering of its Meaning in English needs no introduction. Now in its third edition, its reviews speak for themselves: "This new translation of the Qur''an immediately outdated all the others in the English-speaking world. the result of over twenty-five years of detailed study of the Qur''anic text, the Bewley translation has the advantage of high quality, naturally fluent English, along with the benefit of access to the traditional understanding of the text." Dr. Y. Dutton, Head of Dept. of Arabic and Islamic Studies, Edinburgh University in Journal of Qur''anic Studies, vol. ll, no. 2, 2000, pp. 82-88 "Abdalhaqq and Aisha Bewley''s (translation) has, perhaps, the potential of setting new standards in this discipline... For those who want to familiarise themselves with the content of the Qur''an, this is the ideal translation to start with." Dr. A. Christmann, University of Manchester, Journal of Semitic Studies, 2002, pp. 372-375</p>', 'published', '/catalog/01-1.webp', 'item', 'standard', 'physical', 'cat_quran-mushaf', 'Format', 'buttons', 'small', 651, NULL, NULL, 0, '[]');
