INSERT OR IGNORE INTO product (id, product_number, handle, title, subtitle, description_html, status, thumbnail, unit, product_type, delivery_type, primary_category_id, option_title, option_display, shipping_size, pages, series, release_date, preorder, editorial_reviews) VALUES ('prd_tafsir-ibn-kathir-10-volume-set', 102, 'tafsir-ibn-kathir-10-volume-set', 'Tafsir Ibn Kathir (10 Volume Set)', 'Abridged English translation', '<p>Tafsir Ibn Kathir (Full Set) Darussalam (Abridged) Vol 1-10 Translated and abridged by a group of scholars under the supervision of Sheikh Safiur-Rahman Al-Mubarakpuri. The Qur''an is the revelation of Allah''s Own Words for the guidance of His creatures. Since the Qur''an is the primary source of Islamic teachings, the correct understanding for the Qur''an is necessary for every Muslim. The Tafsir of Ibn Kathir is the most renowned and accepted explanation of the Qur''an in the entire world. In it one finds the best presentation of Ahadith, history, and scholarly commentary. Dar-us-Salam is proud to present for the first time this abridged version of Tafsir Ibn Kathir, which is free from unauthentic Ahadith.</p>', 'published', '/catalog/02-1.webp', 'item', 'standard', 'physical', 'cat_tafsir', 'Format', 'buttons', 'small', 6600, NULL, NULL, 0, '[]');
