INSERT OR IGNORE INTO product (id, product_number, handle, title, subtitle, description_html, status, thumbnail, unit, product_type, delivery_type, primary_category_id, option_title, option_display, shipping_size, pages, series, release_date, preorder, editorial_reviews) VALUES ('prd_maqdis-quran-word-by-word-tajweed-a5', 103, 'maqdis-quran-word-by-word-tajweed-a5', 'Al-Qur''an al-Karim Maqdis', 'Word-by-Word Translation & Colour Coded Tajweed (A5)', '<p>"MAQDIS" AL-QURAN AL-KARIM Word-By-Word Translation & Color Coded Tajweed Hard Cover, A5 Small • If you are looking for a Quran with Arabic-English word-for-word translation , in Rasm Uthmani Script, with color coded tajweed, all-in-one volume, at an excellent price, then look no further. • Every word in this beautiful Quran was translated so that readers can understand every single word or phrase.• It needs to be remembered that not all literal translation represents the exact meaning of the word since the Quran uses varied Arabic language style and sometimes metaphor. To understand the full meaning of the word or the verse , Muhammad Muhsin Khan''s The Holy Quran translation which was approved the University of Madinah, was included on the side. However, to comprehend more of the meaning of the Quran, reading the commentary of the Quran from trusted scholars would be necessary.• Approved by the Department of Islamic Development of Malaysia (JAKIM) and Malaysian Ministry of Home Affairs (KDN)• This Quran comes with a complementary book , " Asbab An Nuzul" ( packaged inside the front cover).• Beautiful hardcover design and lightweight for its A5 size. Pictures do not do justice.• Well laid-out, easy and extremely beneficial, this mushaf is a must have for everyone or every home.• Makes an excellent gift Colour of the cover may vary from the photos but all the contents will be exactly the same . If the right Colour will not be available we will message you as its selling really fast so we may not guarantee the same colour</p>', 'published', '/catalog/03-1.webp', 'item', 'standard', 'physical', 'cat_quran-mushaf', 'Format', 'buttons', 'small', 633, NULL, NULL, 0, '[]');
