INSERT OR IGNORE INTO product (id, product_number, handle, title, subtitle, description_html, status, thumbnail, unit, product_type, delivery_type, primary_category_id, option_title, option_display, shipping_size, pages, series, release_date, preorder, editorial_reviews) VALUES ('prd_quran-indo-pak-script-13-lines', 104, 'quran-indo-pak-script-13-lines', 'The Holy Qur''an, Indo-Pak Script', '13 Lines', '<p>The Holy Quran – 13 Lines Indo-Pak Script is a beautifully presented Mushaf featuring the traditional Indo-Pak Arabic script and a clear 13-line page layout. This format is widely used by Qur’an readers and students across South Asia and is particularly popular for Qur’an reading, memorisation and Hifz. The 13-line layout provides a comfortable and organised reading experience, making it suitable for daily recitation, Qur’an classes, madrasahs and personal study. Ideal for students, Hifz learners, families and regular Qur’an readers, this Mushaf is also a meaningful Islamic gift for family and loved ones. Features The Holy Quran Traditional Indo-Pak script 13 lines per page Clear and easy-to-read Arabic text Ideal for Hifz and memorisation Suitable for Qur’an classes and madrasahs Perfect for daily recitation and revision Suitable for home and personal study Meaningful Islamic gift</p>', 'published', '/catalog/04-1.webp', 'item', 'standard', 'physical', 'cat_quran-mushaf', 'Format', 'buttons', 'small', NULL, NULL, NULL, 0, '[]');
