INSERT OR IGNORE INTO product (id, product_number, handle, title, subtitle, description_html, status, thumbnail, unit, product_type, delivery_type, primary_category_id, option_title, option_display, shipping_size, pages, series, release_date, preorder, editorial_reviews) VALUES ('prd_juz-amma-translation-transliteration', 105, 'juz-amma-translation-transliteration', 'Juz ''Amma', 'With Meanings, Translation and Transliteration in English', '<p>Juzk Amma with Meanings Translation and Transliteration in English This is Amma part of the Tajweed Quran, Part thirty , starts from sura Naas till sura "naba", it includes translations and transliteration into English. Translation: meanings of the Quranic versus are translated into English and placed on the margins around the Arabic text. Transliteration: Arabic letters are presented by English letters with added symbols in order to give the same sound of Arabic letters. English transliteration makes it easier for the speakers of the English language to read the Tajweed Quran in Arabic pronunciation using the English alphabet letters. Considering that this Part contains small suras; it is a perfect start for kids, beginners and students. This Amma Part comes in the standard portrait form, with a nice glossy soft cover. Each page contains 15 lines as any standard Quran. This part of the Tajweed Quran is in Hafs narration. All our Tajweed Quran products - including this item - come with the following: 1- Colour coded letters: to present the Tajweed rules, very good and simple way to learn and apply Tajweed rules . 2- Obvious script: extra spaces were added between the words in order to make it easier to read and recite the Quran. 3- Permissible stops: long spaces were added at certain places where it is permissible to stop. It helps to avoid stopping at wrong places or times. 4- A set of very useful indexes such as: Surahs Colour Index, Subject Index. 5- Tajweed rules explained in details with helpful illustration.</p>', 'published', '/catalog/05-1.webp', 'item', 'standard', 'physical', 'cat_quran-mushaf', 'Format', 'buttons', 'small', 56, NULL, NULL, 0, '[]');
