INSERT OR IGNORE INTO product (id, product_number, handle, title, subtitle, description_html, status, thumbnail, unit, product_type, delivery_type, primary_category_id, option_title, option_display, shipping_size, pages, series, release_date, preorder, editorial_reviews) VALUES ('prd_sahih-al-bukhari-9-volume-set', 106, 'sahih-al-bukhari-9-volume-set', 'Sahih al-Bukhari (9 Volume Set)', 'Arabic-English', '<p>Sahih Al-Bukhari (9 Vol. Set) Generally regarded as the single most authentic collection of Ahadith, Sahih Al-Bukhari covers almost all aspects of life in providing proper guidance from the messenger of Allah. This 9-Volume Bukhari is the work of over 16 years by Imam Bukhari who before writing any Hadith in this book performed two Rakat prayer of guidance from Allah and when he was sure of the Hadith''s authenticity, he wrote it in the book. Tremendous amounts of errors exist in the translations by other translators. To eliminate the problem Dar-us-Salam spent over 3 years in the publication of this book and presented a book which is translated into English in a very easy and simple language, so that all readers can understand it without difficulty. This is the unabridged version consisting of 7563 ahadith (about 4000 pages) which are presented neatly in smaller books format and printed on fine paper. Each book (subtopics in each volume categorized by very broad topics such as the Book of As-Salat) contains many chapters which represent one logical unit of Ahadith. Each book contains anywhere from one to 150 chapters with each chapter containing several Ahadith. This book will be a great addition to your library while giving you a true perspective on the traditions of the Prophet (PBUH). In Imam Bukhari''s ''Al-Jami-al-Sahih'' (Sahih Al Bukhari) the Imam had recorded all the Sayings of the Prophet which he found to be genuine after thorough examination and scrutiny. He spent sixteen years in research and examined more than sixty thousand Sayings from which he selected only sayings whose genuineness and accuracy he established beyond the slightest doubt. Deducting duplicates, the Imam''s collection contain about four thousand distinct Sayings.</p>', 'published', '/catalog/06-1.webp', 'item', 'standard', 'physical', 'cat_hadith', 'Format', 'buttons', 'small', 4050, NULL, NULL, 0, '[]');
