INSERT OR IGNORE INTO product (id, product_number, handle, title, subtitle, description_html, status, thumbnail, unit, product_type, delivery_type, primary_category_id, option_title, option_display, shipping_size, pages, series, release_date, preorder, editorial_reviews) VALUES ('prd_sahih-muslim-7-volume-set', 107, 'sahih-muslim-7-volume-set', 'Sahih Muslim (7 Volume Set)', 'English-Arabic', '<p>English Translation of Sahih Muslim : 7 Volume Set English Translation of Sahih Muslim : 7 Volume Set Set By Nasiruddin Al-Khattab. Sahih Muslim is the most authentic book of Hadith after Sahih Al-Bukhari and contains 7,563 Ahadith. The Muslim Scholars have agreed that all of the Ahadith in Sahih Muslim are authentic. Thus, Darussalam realized the great benefit of publishing the full version of Sahih Muslim in the English language in the best presentation. Much care has been taken in rendering these Ahadith into a clear and simple style of modern English. This fine-quality edition of Sahih Muslim has been verified by Dar-us-Salam Publications extensively. Its translation has been checked several times as not only to avoid mistranslating but also to avoid misinterpreting the ahadith as done by many translators of the current times in order to rush the product to market or to their lack of understanding of the Arabic language. Unlike other publishers which leave you wondering about the meaning of the ahadith, the unclear wording has been explained in the brackets. There are also footnotes on bottom of some of the pages, when the term cannot be explained in the brackets. This edition of Dar-us-Salam is nice in that it starts off by drawing a life sketch of Imam Muslim. Then, it goes on to the introduction of Sahih Muslim by Imam Muslim himself where he explains the difference between different narrators and level of trustworthiness. This edition is also different from other publishers in that the text is side by side with Arabic so you have access to both English and Arabic at the same time. Furthermore, the book regarding reporting from the trustworthy narrators have been placed first while other books follow it.</p>', 'published', '/catalog/07-1.webp', 'item', 'standard', 'physical', 'cat_hadith', 'Format', 'buttons', 'small', 4000, NULL, NULL, 0, '[]');
