INSERT OR IGNORE INTO product (id, product_number, handle, title, subtitle, description_html, status, thumbnail, unit, product_type, delivery_type, primary_category_id, option_title, option_display, shipping_size, pages, series, release_date, preorder, editorial_reviews) VALUES ('prd_riyad-us-saliheen-2-volume-set', 108, 'riyad-us-saliheen-2-volume-set', 'Riyad us-Saliheen (2 Volume Set)', 'The Gardens of the Righteous', '<p>Riyad Us Saliheen : 2 volume Set We praise ALLAH that He enabled us to publish many books on religious topics in the Arabic, Urdu and English languages which acclaimed great popularity in Arab countries as well as in America, France and European countries besides Pakistan, India and many African countries. We try to present publications based on authentic research material in lines with the Qur''an and Sunnah, and that are free from every type of vague conception, weak authority and false ideas. Now, we have published Riyad-us-Saliheen with the same spirit and same tradition of good research work, professional editing and excellent printing standard. The book was compiled by Imam An-Nawawi who was the great scholar of Hadith and Fiqh of his time. Commentaries on the Ahadith have been added by Hafiz Salahuddin Yusuf of Pakistan who had originally executed them for the Urdu edition of this book. The English translation of the book and the - commentaries was performed by Dr. Muhammad Amin and Abu Usamah Al-Arabi bin Razduq who have performed their task with utmost care and profound interest. We, hopefully, can proclaim that it is the best representation of Riyad-us-Saliheen ever produced in any language any where. May Allah accept our sincere efforts regarding the propagation of His religion throughout the world, and bestow on us His blessings to fulfil our resolutions in this regard -Amin! Abdul Malik Mujahid General Manager Darussalam</p>', 'published', '/catalog/08-1.webp', 'item', 'standard', 'physical', 'cat_hadith', 'Format', 'buttons', 'small', 1413, NULL, NULL, 0, '[]');
