INSERT OR IGNORE INTO product (id, product_number, handle, title, subtitle, description_html, status, thumbnail, unit, product_type, delivery_type, primary_category_id, option_title, option_display, shipping_size, pages, series, release_date, preorder, editorial_reviews) VALUES ('prd_bulugh-al-maram', 109, 'bulugh-al-maram', 'Bulugh al-Maram', 'Attainment of the Objective', '<p>Bulugh Al Maram: Attainment of the Objective Bulugh Al-Maram is based upon the Ahadith of our Prophet which have been the sources of Islamic Jurisprudence. Al-Hafiz Ibn Hajar Al-Asqalani (Hijrah 777-853) has recorded the true significance of the Ahadith and their origins & also made a comparison of the versions, if the sources are more than one</p>', 'published', '/catalog/09-1.webp', 'item', 'standard', 'physical', 'cat_fiqh-aqidah', 'Format', 'buttons', 'small', 520, NULL, NULL, 0, '[]');
