INSERT OR IGNORE INTO product (id, product_number, handle, title, subtitle, description_html, status, thumbnail, unit, product_type, delivery_type, primary_category_id, option_title, option_display, shipping_size, pages, series, release_date, preorder, editorial_reviews) VALUES ('prd_fortress-of-the-muslim-pocket', 110, 'fortress-of-the-muslim-pocket', 'Fortress of the Muslim (Pocket Size)', 'Invocations from the Qur''an and Sunnah', '<p>Fortress of the Muslim (Pocket Size) Invocations from the Qur''an & Sunnah. Translation of Hisnul-Muslim. (aka ''Citadel of the Believer'') This is a very beautiful booklet consists of many authentic Dua''s (supplications) for a Muslim to supplicate on a daily basis and on special occasions. Author''s Note: This book is an abridgement of my earlier work entitled, Adh-Dhikr wad-Du''a wal-''llaj bir-Ruqyah mina''-Kitab was-Sunnah. In order to make it small and easily portable, I have chosen only the section on words of remembrance for this abridgement. To achieve this, I only mentioned the text of the words of remembrance instead of the entire Hadith. I also limited myself to mentioning only one or two references from the original book for each Hadith. Whoever would like to know about the Companion who related a particular Hadith, or more information about where it is recorded, should refer to the original work (mentioned above). I ask Allah the Glorious, the Mighty, by His beautiful Names and by His sublime Attributes to accept this as having been done sincerely for His sake alone. I ask Him to bring me its benefits during my lifetime and after my death. May those who read it, those who print it, or have had any role in distributing it, benefit from it also. Surely He, glory be unto Him, is Capable of all things. May the peace and blessings of Allah be upon our Prophet, Muhammad, and upon his family and Companions and whoever follows them in piety until the Day of Judgement. Said bin Ali bin Wahaf Al-Qahtani</p>', 'published', '/catalog/10-1.webp', 'item', 'standard', 'physical', 'cat_islamic-living', 'Format', 'buttons', 'small', NULL, NULL, NULL, 0, '[]');
