INSERT OR IGNORE INTO product (id, product_number, handle, title, subtitle, description_html, status, thumbnail, unit, product_type, delivery_type, primary_category_id, option_title, option_display, shipping_size, pages, series, release_date, preorder, editorial_reviews) VALUES ('prd_kitab-at-tawheed', 111, 'kitab-at-tawheed', 'Kitab at-Tawheed', 'The Book of Tawheed, with commentary', '<p>This is a commentary on the book of Shaikh Muhammed ibn Abdul Wahhab’s Kitab At-Tawheed (The Book of Tawheed). Kitab At-Tawheed is an excellent and comprehensive book. It illuminates to the reader the light of tawheed the Oneness of Allah tawheed, the very foundation of this deen, the single most important concept and the purpose behind our creation.</p>', 'published', '/catalog/11-1.webp', 'item', 'standard', 'physical', 'cat_fiqh-aqidah', 'Format', 'buttons', 'small', 553, NULL, NULL, 0, '[]');
