INSERT OR IGNORE INTO product (id, product_number, handle, title, subtitle, description_html, status, thumbnail, unit, product_type, delivery_type, primary_category_id, option_title, option_display, shipping_size, pages, series, release_date, preorder, editorial_reviews) VALUES ('prd_noble-quran-hilali-khan-medium', 112, 'noble-quran-hilali-khan-medium', 'The Noble Qur''an (Medium)', 'Arabic text with English meanings and commentary', '<p>Noble Quran Medium H/C Interpretation of the meanings of the Noble Qur''an with Arabic text in the modern English language. A summarized version of At-Tabari, Al-Qurtubi and Ibn Kathir with comments from Sahih Al-Bukhari. This 1 volume summarized version offers brief commentary and Ahadith wherever necessary. This unique combination of commentary and relevant Ahadith makes this a very useful study reference tool.</p>', 'published', '/catalog/12-1.webp', 'item', 'standard', 'physical', 'cat_quran-mushaf', 'Format', 'buttons', 'small', 927, NULL, NULL, 0, '[]');
