INSERT OR IGNORE INTO product (id, product_number, handle, title, subtitle, description_html, status, thumbnail, unit, product_type, delivery_type, primary_category_id, option_title, option_display, shipping_size, pages, series, release_date, preorder, editorial_reviews) VALUES ('prd_the-sealed-nectar', 113, 'the-sealed-nectar', 'The Sealed Nectar', 'Ar-Raheeq al-Makhtum: Biography of the Noble Prophet', '<p>Ar-Raheeq Al-Makhtum - Biography of Prophet Muhammad Pbuh. (MEDIUM SIZE) A complete authoritative book on the life of Prophet Muhammad (S) By: Safi Ur-Rehman Mubarakpuri. The Sealed Nectar was honoured by the World Muslim League as first prize winner book. Whoever wants to know the whole life style of the Prophet in detail must read this book. Muhammad (S) is the Messenger of Allah, and those who are with him, are severe against the disbelievers, and merciful among themselves. You see them bowing and falling down prostrate (in prayer), seeking bounty from Allah and (His) Good Pleasure. The mark of them (i.e. of their Faith) is on their faces (fore heads) from the traces of prostration (during prayers). This is their description in the Taurah (Torah). But their description in the Injeel (Gospel) is like a (sown) seed which sends forth its shoot, then makes it strong, and becomes thick and it stands straight on its stem, delighting the sowers, that He may enrage the disbelievers with them. Allah has promised those among them who believe and do righteous good deeds, forgiveness and a mighty reward (Paradise). (Al-Fath: 29) The Prophet Muhammad (S) said: "The example of guidance and knowledge with which Allah has sent me is like abundant rain falling on the earth. Some of which was fertile soil that absorbed rain-water and brought forth vegetation and grass in abundance. (And) another portion of it was hard and held the rain-water and Allah benefited the people with it and they utilized it for drinking (making their animals drink from it) and to irrigate the land for cultivation. (And) a portion of it was barren which could neither hold the water nor bring forth vegetation (then that land gave no benefits).</p>', 'published', '/catalog/13-1.webp', 'item', 'standard', 'physical', 'cat_seerah-history', 'Format', 'buttons', 'small', 588, NULL, NULL, 0, '[]');
