INSERT OR IGNORE INTO product (id, product_number, handle, title, subtitle, description_html, status, thumbnail, unit, product_type, delivery_type, primary_category_id, option_title, option_display, shipping_size, pages, series, release_date, preorder, editorial_reviews) VALUES ('prd_stories-of-the-prophets', 114, 'stories-of-the-prophets', 'Stories of the Prophets', 'From al-Bidayah wan-Nihayah', '<p>Stories of the Prophets Immerse yourself in the captivating world of the prophets with this extraordinary book, "Stories of the Prophets." Drawing from the renowned masterpiece ''Al-Bidayah wan-Nihayah'' (The Beginning and the End) by Ibn Kathir, a celebrated Muslim exegete and historian, this literary gem takes you on a profound journey through Islamic history. With meticulous attention to detail, the book intricately weaves together the stories of the prophets, supported by verses from the Qur''an and the cherished traditions of the Prophet (S). Ibn Kathir''s careful research and extensive knowledge shine through as he explores the lives of the prophets, providing a comprehensive and enlightening account of their extraordinary experiences. Delving into the historical significance of each event, the book ensures authenticity by conducting a comparative study of various sources. Moreover, Ibn Kathir artfully presents the viewpoints and interpretations of the esteemed Qur''anic scholars of his time, offering a rich and diverse understanding of the prophets'' stories."Stories of the Prophets" is a treasure trove of knowledge, offering invaluable insights into the lives and teachings of the messengers chosen by Allah. Whether you seek spiritual enlightenment, a deeper understanding of Islamic history, or simply an engaging read, this book is a must-have for every seeker of truth.</p>', 'published', '/catalog/14-1.webp', 'item', 'standard', 'physical', 'cat_seerah-history', 'Format', 'buttons', 'small', 576, NULL, NULL, 0, '[]');
