INSERT OR IGNORE INTO product (id, product_number, handle, title, subtitle, description_html, status, thumbnail, unit, product_type, delivery_type, primary_category_id, option_title, option_display, shipping_size, pages, series, release_date, preorder, editorial_reviews) VALUES ('prd_men-and-women-around-the-messenger', 115, 'men-and-women-around-the-messenger', 'Men & Women Around the Messenger', 'One hundred Companions of the Prophet', '<p>Men & Women Around the Messenger The author has chosen one hundred personalities amongst the Companions. He compiled narrations, hadiths and incidences that contributed to the distinction of these individuals who have no similitude in the history of mankind after the Prophets of Allah and His Messengers. Their excellence is further clearly established from the study of these individuals, their attributes and their characters with which they were embellished. For this reason, they were from the best of people ever raised up for mankind.</p>', 'published', '/catalog/15-1.webp', 'item', 'standard', 'physical', 'cat_seerah-history', 'Format', 'buttons', 'small', 608, NULL, NULL, 0, '[]');
