INSERT OR IGNORE INTO product (id, product_number, handle, title, subtitle, description_html, status, thumbnail, unit, product_type, delivery_type, primary_category_id, option_title, option_display, shipping_size, pages, series, release_date, preorder, editorial_reviews) VALUES ('prd_history-of-islam-abu-bakr', 116, 'history-of-islam-abu-bakr', 'History of Islam: Abu Bakr as-Siddiq', 'The Age of the Rightly Guided Caliphs', '<p>History of Islam : Abu Bakr As-Siddiq R.A. : The Age of Rightly Guided Caliphs A Reader Series Abu Bakr As-Siddiq Rightly-Guided Caliphs History of Islam The age of the rightly guided caliphs Al-Khulafa Ar-Rashidun This is the first volume from this series, which deals with the life of Abū Bakr as-Șiddīq, the first of the Four Rightly-Guided Caliphs. No other person in the History of Islam can be compared to him when it comes to truthfulness, insight into Islamic teachings and devotion to ALLAH and His Messenger صلی الله علیهِ وآله وسلم. He was outstanding and unique in his commitment, sincerity, and whole-hearted support and assistance to the Prophet. Our past, present, and future are interconnected and interdependent. Therefore, knowing and understanding our history is not optional: it is essential. Darussalam presents the entire History of Islam to our youth in language that appeals to them, in a simple yet lucid manner. The first four volumes in this series explore Islamic history during the period of the first Four Rightly-Guided Caliphs. Later volumes would be devoted to the History of Islam, down through the ages to modern times, insha''ALLAH.</p>', 'published', '/catalog/16-1.webp', 'item', 'standard', 'physical', 'cat_seerah-history', 'Format', 'buttons', 'small', 141, 'History of Islam: The Rightly Guided Caliphs', NULL, 0, '[]');
