INSERT OR IGNORE INTO product (id, product_number, handle, title, subtitle, description_html, status, thumbnail, unit, product_type, delivery_type, primary_category_id, option_title, option_display, shipping_size, pages, series, release_date, preorder, editorial_reviews) VALUES ('prd_brief-illustrated-guide-to-understanding-islam', 117, 'brief-illustrated-guide-to-understanding-islam', 'A Brief Illustrated Guide to Understanding Islam', NULL, '<p>A Brief Illustrated Guide to Understanding Islam This book is specifically written for non-Muslims to help them better understand Islam. Some of the topics in this book are: - - Pillars of faith. - Some benefits of Islam. - General information on Islam. - The status of women in Islam. - What Islam says about terrorism? - Evidence that Islam is a true religion. - Correction of some misconceptions about Islam. - Proofs that the Qur''an is the literal word of God. - Scientific miracles in the Qur''an with scientific illustrations. - Why Muhammad صلی الله علیه وآله وسلم is truly a prophet sent by God? Features of the book: * 43 illustrations, 39 in colour. * More than 375,000 copies have been printed. * Laminated 350 gm cover, High quality printing. * 76 colourful pages on glossy, coated, 115 gm paper.</p>', 'published', '/catalog/17-1.webp', 'item', 'standard', 'physical', 'cat_islamic-living', 'Format', 'buttons', 'small', 74, NULL, NULL, 0, '[]');
