INSERT OR IGNORE INTO product (id, product_number, handle, title, subtitle, description_html, status, thumbnail, unit, product_type, delivery_type, primary_category_id, option_title, option_display, shipping_size, pages, series, release_date, preorder, editorial_reviews) VALUES ('prd_my-first-prayer-book', 119, 'my-first-prayer-book', 'My First Prayer Book', 'Wudu, Salah and daily du''as for children', '<p>My First Prayer BookDarussalam’s My First Prayer Book is a beautifully illustrated guide designed to teach children the fundamentals of prayer in an engaging and easy-to-understand way. This comprehensive book covers: How to Perform Wudhu: Step-by-step instructions for ablution, complete with vibrant illustrations and QR codes for video guidance. How to Perform Salah: A clear and practical guide to each stage of prayer, ensuring children learn correctly from the very beginning. Daily Duas and Athkar: A collection of essential supplications and remembrances, encouraging the habit of connecting with Allah throughout the day. Written in accordance with the Quran and Sunnah, My First Prayer Book ensures children learn the Islamic way of performing these important acts of worship. With its interactive features and child-friendly design, this book is the perfect tool for parents, teachers, and caregivers to instill the love of prayer in young hearts.</p>', 'published', '/catalog/19-1.webp', 'item', 'standard', 'physical', 'cat_childrens-books', 'Format', 'buttons', 'small', 60, NULL, NULL, 0, '[]');
