INSERT OR IGNORE INTO product (id, product_number, handle, title, subtitle, description_html, status, thumbnail, unit, product_type, delivery_type, primary_category_id, option_title, option_display, shipping_size, pages, series, release_date, preorder, editorial_reviews) VALUES ('prd_prophet-muhammad-stories-gift-set', 120, 'prophet-muhammad-stories-gift-set', 'Prophet Muhammad Stories (Gift Set)', 'Four hardbound Seerah storybooks, ages 7+', '<p>Prophet Muhammad Stories Gift Set is a beautifully presented collection of inspiring Seerah stories specially selected for children aged 7 years and above. This four-book hardbound set introduces young readers to the life, character, and mission of Prophet Muhammad ﷺ through engaging stories and child-friendly explanations. Through these treasured moments from the Prophet’s ﷺ life, children can learn about his kindness, patience, mercy, courage, and excellent character while discovering how to apply his timeless teachings in their own daily lives. With colourful illustrations and an attractive gift box design, this collection is perfect for home reading, bedtime stories, Islamic schools, and family learning. It makes a meaningful gift for children and grandchildren. Features Complete 4-book Prophet Muhammad ﷺ Seerah gift set Specially designed for children aged 7+ Inspiring stories from the life of Prophet Muhammad ﷺ Helps children learn Prophetic manners and values Colourful, child-friendly illustrations Hardbound books with premium presentation Suitable for home, school and Islamic learning Encourages love for the Prophet ﷺ and his teachings Beautiful Islamic gift for children</p>', 'published', '/catalog/20-1.webp', 'item', 'standard', 'physical', 'cat_childrens-books', 'Format', 'buttons', 'small', NULL, NULL, NULL, 0, '[]');
